package com.formation.loan.controller; import com.formation.loan.dto.*; import com.formation.loan.service.LoanService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
@RestController @RequestMapping("/api/loans") public class LoanController {private final LoanService service;public LoanController(LoanService s){service=s;} @GetMapping public java.util.List<LoanResponse> findAll(){return service.findAll();} @GetMapping("/{id}") public LoanResponse findById(@PathVariable Long id){return service.findById(id);} @PostMapping public ResponseEntity<LoanResponse> create(@Valid @RequestBody LoanRequest r){LoanResponse l=service.create(r);URI u=ServletUriComponentsBuilder.fromCurrentRequest().path("/{id}").buildAndExpand(l.id()).toUri();return ResponseEntity.created(u).body(l);} @PatchMapping("/{id}/return") public LoanResponse returnLoan(@PathVariable Long id){return service.returnLoan(id);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}}
